input.sparql:
SELECT ?s ?id WHERE {
  ?s a brick:Electric_Power ;
     brick:hasLocation ?loc .
  ?s ref:hasExternalReference ?ref .
  ?ref ref:hasTimeseriesId ?id .
  ?loc a brick:Building .
}

SELECT ?s ?id ?class WHERE {
  ?s a brick:Building_Electrical_Meter .
  ?s ref:hasExternalReference ?ref .
  ?ref ref:hasTimeseriesId ?id .
  ?s a ?class .
}
